package com.tanerinal.education.service;import com.tanerinal.education.mapper.ReconciliationMapper;import io.micrometer.core.instrument.*;import net.javacrumbs.shedlock.spring.annotation.SchedulerLock;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;@Service public class PaymentReconciliationJob{private final ReconciliationMapper mapper;private final Counter detected;public PaymentReconciliationJob(ReconciliationMapper mapper,MeterRegistry registry){this.mapper=mapper;detected=registry.counter("education.payment.reconciliation.detected");Gauge.builder("education.payment.reconciliation.open",mapper,ReconciliationMapper::openIssues).register(registry);}@Scheduled(fixedDelayString="${education.reconciliation.delay:60000}")@SchedulerLock(name="paymentReconciliation",lockAtLeastFor="PT1S",lockAtMostFor="PT55S")public void reconcile(){detected.increment(mapper.detectExpired());}}
